13	type Scheduler struct {
14		now   func() time.Time
15		store Repository
16		plan  Plan
17	}
18	
19	// NewScheduler builds a scheduler over store that honors plan and reads the
20	// current time from now.
21	func NewScheduler(store Repository, plan Plan, now func() time.Time) (*Scheduler, error) {
22		if now == nil {
23			return nil, errors.New("scheduler: nil clock")
24		}
25		return &Scheduler{now: now, store: store, plan: plan}, nil
26	}
27	
28	// Take records a new snapshot for deviceID, provided the plan is open and the
29	// retention config is usable.
30	func (s *Scheduler) Take(raw map[string]string, deviceID string) (models.Snapshot, error) {
31		now := s.now()
32		if !s.plan.Open(now) {
33			return models.Snapshot{}, fmt.Errorf("scheduler: plan closed at %s", now.Format("15:04"))
34		}
35		if retentionDays(raw) == 0 {
36			return models.Snapshot{}, errors.New("scheduler: retention unset, snapshots would never expire")
37		}
38		sn := New(deviceID, now)
39		if err := s.store.Put(sn); err != nil {
40			return models.Snapshot{}, err
41		}
42		return sn, nil
43	}
