45	// Prune deletes the snapshots of deviceID that the retention policy in raw has
46	// expired and returns the deleted records.
47	func (s *Scheduler) Prune(raw map[string]string, deviceID string) ([]models.Snapshot, error) {
48		snaps, err := s.store.List(deviceID)
49		if err != nil {
50			return nil, err
51		}
52		expired, err := s.applyPolicy(raw, snaps)
53		if err != nil {
54			return nil, err
55		}
56		for _, sn := range expired {
57			if err := s.store.Delete(sn.ID); err != nil {
58				return nil, err
59			}
60		}
61		return expired, nil
62	}
