10	const minutesPerDay = 24 * 60
11	
12	// Window is a daily time-of-day interval during which snapshots may be taken.
13	// A window that ends before it starts wraps past midnight.
14	type Window struct {
15		start int // minutes since midnight
16		end   int // minutes since midnight
17	}
18	
19	// ParseWindow builds a Window from two "HH:MM" clock times.
20	func ParseWindow(start, end string) (Window, error) {
21		s, err := parseClock(start)
22		if err != nil {
23			return Window{}, fmt.Errorf("window start: %w", err)
24		}
25		e, err := parseClock(end)
26		if err != nil {
27			return Window{}, fmt.Errorf("window end: %w", err)
28		}
29		if s == e {
30			return Window{}, fmt.Errorf("window %s-%s is empty", start, end)
31		}
32		return Window{start: s, end: e}, nil
33	}
34	
35	func parseClock(v string) (int, error) {
36		t, err := time.Parse("15:04", v)
37		if err != nil {
38			return 0, fmt.Errorf("clock time %q: want HH:MM", v)
39		}
40		return t.Hour()*60 + t.Minute(), nil
41	}
42	
43	// Contains reports whether t falls inside the window.
44	func (w Window) Contains(t time.Time) bool {
45		m := t.Hour()*60 + t.Minute()
46		if w.start < w.end {
47			return m >= w.start && m < w.end
48		}
49		return m >= w.start || m < w.end
50	}
51	
52	// Duration returns how long the window stays open each day.
53	func (w Window) Duration() time.Duration {
54		span := w.end - w.start
55		if span < 0 {
56			span += minutesPerDay
57		}
58		return time.Duration(span) * time.Minute
59	}
60	
61	// String renders the window as "HH:MM-HH:MM".
62	func (w Window) String() string {
63		return fmt.Sprintf("%02d:%02d-%02d:%02d", w.start/60, w.start%60, w.end/60, w.end%60)
64	}
65	
66	// Plan is the set of windows during which a device may be snapshotted.
67	type Plan struct {
68		windows []Window
69	}
70	
71	// NewPlan builds a Plan from at least one window. The plan keeps its own copy
72	// so later changes to the caller's slice cannot reorder or shrink it.
73	func NewPlan(windows []Window) (Plan, error) {
74		if len(windows) == 0 {
75			return Plan{}, errors.New("plan: no windows")
76		}
77		return Plan{windows: slices.Clone(windows)}, nil
78	}
79	
80	// Open reports whether any window of the plan contains t.
81	func (p Plan) Open(t time.Time) bool {
82		return slices.ContainsFunc(p.windows, func(w Window) bool { return w.Contains(t) })
83	}
84	
85	// Windows returns the plan's windows. Callers get their own copy: the plan is
86	// shared by the scheduler and the status page, and neither may edit it.
87	func (p Plan) Windows() []Window {
88		return slices.Clone(p.windows)
